  /// timesheet. Required when status is 'rejected'; null otherwise. Allows the
  /// employee to understand what must be corrected before resubmission.
  rejection_reason String?

  /// Timestamp when this timesheet record was first created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this timesheet record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
