  project            erp_hrm_projects             @relation(fields: [project_id], references: [id], onDelete: Cascade)
  task               erp_hrm_tasks?               @relation(fields: [task_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([organization_member_id])
  @@index([project_id, started_at])
  @@index([task_id, started_at])
