export async function test_api_organization_member_detail_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Register the first member (organization owner)
  const ownerConnection: api.IConnection = { host: connection.host };
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  await authorize_member_join(ownerConnection, {
    body: {
      email: ownerEmail,
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  // Step 2: Create an organization (owner connection is automatically updated with auth token)
  const organization =
    await generate_random_erp_hrm_member_organizations_create(
      ownerConnection,
      {},
    );
  typia.assert(organization);
  // Step 3: Register a second member (employee)
  const employeeConnection: api.IConnection = { host: connection.host };
  const employeeEmail = typia.random<string & tags.Format<"email">>();
  const employeeAuth = await authorize_member_join(employeeConnection, {
    body: {
      email: employeeEmail,
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(employeeAuth);
  // Step 4: Add the second member to the organization
  // Use the owner's role ID since it's the only role ID accessible from the created organization
  const roleId = organization.owner.role.id;
  const positionTitle = "Senior Engineer";
  const orgMember =
    await generate_random_erp_hrm_member_organization_members_create(
      ownerConnection,
      {
        body: {
          memberId: employeeAuth.member.id,
          roleId: roleId,
          employmentType: "full-time",
          position: positionTitle,
          departmentId: null,
        },
      },
    );
  typia.assert(orgMember);
  // Step 5: Retrieve the organization member detail by ID
  const memberDetail = await api.functional.erpHrm.members.at(ownerConnection, {
    memberId: orgMember.id,
  });
  typia.assert(memberDetail);
  // Assertions - validate business logic
  TestValidator.equals("member id matches", memberDetail.id, orgMember.id);
  TestValidator.equals(
    "organization id matches",
    memberDetail.organization_id,
    organization.id,
  );
  TestValidator.equals(
    "email matches employee email",
    memberDetail.email,
    employeeEmail,
  );
  TestValidator.equals(
    "employment type is full-time",
    memberDetail.employment_type,
    "full-time",
  );
  TestValidator.equals("status is active", memberDetail.status, "active");
  TestValidator.equals(
    "position is Senior Engineer",
    memberDetail.position,
    positionTitle,
  );
  TestValidator.equals("department is null", memberDetail.department, null);
  TestValidator.equals("deleted_at is null", memberDetail.deleted_at, null);
}

