  TestValidator.equals(
    "organization id unchanged",
    updated.id,
    organization.id,
  );
  TestValidator.equals("organization name updated", updated.name, newName);
  TestValidator.equals(
    "organization description updated",
    updated.description,
    newDescription,
  );
  TestValidator.equals(
    "organization logo_url updated",
    updated.logo_url,
    newLogoUrl,
  );
  TestValidator.equals(
