  // ──────────────────────────────────────────────────────────────────────────
  // 12. Pagination: page=1, limit=1
  // ──────────────────────────────────────────────────────────────────────────
  const paginated = await api.functional.erpHrm.member.projects.members.index(
    managerConnection,
