export async function test_api_task_history_access_denied_for_non_project_member(
  connection: api.IConnection,
): Promise<void> {
  // ── Step 1: Register member #1 (owner) ──────────────────────────────────
  const ownerConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(ownerConnection, {});
  // ── Step 2: Create an organization (member #1 becomes Owner) ────────────
  const organization =
    await generate_random_erp_hrm_member_organizations_create(
      ownerConnection,
      {},
    );
  typia.assert(organization);
  // ── Step 3: Create a custom role WITHOUT project:manage permission ───────
  // The outsider will get this role so they have org access but not project access
  const customRole =
    await generate_random_erp_hrm_member_organizations_roles_create(
      ownerConnection,
      {
        body: {
          name: "outsider-role-" + RandomGenerator.alphabets(6),
          permissions: ["employee:view"],
        },
        params: {
          organizationId: organization.id,
        },
      },
    );
  typia.assert(customRole);
  // ── Step 4: Create a project (owner has project:manage) ─────────────────
  const project = await generate_random_erp_hrm_member_projects_create(
    ownerConnection,
    {},
  );
  typia.assert(project);
  // ── Step 5: Create a task within the project ────────────────────────────
  // Task creation generates an initial task history entry
  const task = await generate_random_erp_hrm_member_projects_tasks_create(
    ownerConnection,
    {
      params: {
        projectId: project.id,
      },
    },
  );
  typia.assert(task);
  // ── Step 6: Register member #2 (the outsider) ───────────────────────────
  const outsiderConnection: api.IConnection = { host: connection.host };
  const outsider = await authorize_member_join(outsiderConnection, {});
  typia.assert(outsider);
  // ── Step 7: Add member #2 to the organization with the custom role ───────
  // Intentionally do NOT add them to the project
  const orgMember =
    await generate_random_erp_hrm_member_organizations_members_create(
      ownerConnection,
      {
        body: {
          memberId: outsider.id,
          roleId: customRole.id,
          employmentType: "full-time",
        },
        params: {
          organizationId: organization.id,
        },
      },
    );
  typia.assert(orgMember);
  // ── Step 8: Primary Test — Access Denied for outsider ───────────────────
  // Member #2 is in the org but NOT in the project and has no project:manage
  await TestValidator.error(
    "non-project member should be denied access to task history",
    async () => {
      await api.functional.erpHrm.member.projects.tasks.histories.index(
        outsiderConnection,
        {
          projectId: project.id,
          taskId: task.id,
          body: {},
        },
      );
    },
  );
  // ── Step 9: Positive Control — Owner CAN access task history ────────────
  const historyPage =
    await api.functional.erpHrm.member.projects.tasks.histories.index(
      ownerConnection,
      {
        projectId: project.id,
        taskId: task.id,
        body: {},
      },
    );
  typia.assert(historyPage);
  TestValidator.predicate(
    "owner can access task history with at least one entry",
    historyPage.data.length >= 1,
  );
}

