import { MyGlobal } from "../MyGlobal";
import { ErpHrmRoleCollector } from "../collectors/ErpHrmRoleCollector";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { ErpHrmRoleTransformer } from "../transformers/ErpHrmRoleTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postErpHrmMemberOrganizationsOrganizationIdRoles(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
  body: IErpHrmRole.ICreate;
}): Promise<IErpHrmRole> {
  const VALID_PERMISSION_CODES = new Set([
    "org:manage",
    "employee:manage",
    "employee:view",
    "project:manage",
    "project:view",
    "time:manage",
    "time:approve",
    "time:view_all",
    "report:view",
  ]);
  // Step 1: Verify member belongs to the organization
  const orgMember =
    await MyGlobal.prisma.erp_hrm_organization_members.findFirst({
      where: {
        organization_id: props.organizationId,
        member_id: props.member.id,
        deleted_at: null,
      },
      select: {
        id: true,
        role: {
          select: {
            permissions: {
              select: {
                permission_code: true,
              },
            },
          },
        },
      },
    });
  if (orgMember === null) {
    throw new HttpException("Forbidden", 403);
  }
  // Step 2: Verify org:manage permission
  const hasOrgManage = orgMember.role.permissions.some(
    (p) => p.permission_code === "org:manage",
  );
  if (!hasOrgManage) {
    throw new HttpException("Forbidden", 403);
  }
  // Step 3: Validate permission codes
  for (const code of props.body.permissions) {
    if (!VALID_PERMISSION_CODES.has(code)) {
      throw new HttpException(`Invalid permission code: ${code}`, 422);
    }
  }
  // Step 4: Check name uniqueness within organization
  const existing = await MyGlobal.prisma.erp_hrm_roles.findFirst({
    where: {
      erp_hrm_organization_id: props.organizationId,
      name: props.body.name,
    },
    select: { id: true },
  });
  if (existing !== null) {
    throw new HttpException(
      "Conflict: role name already exists in this organization",
      409,
    );
  }
  // Step 5: Create role with permissions using Collector + Transformer
  const created = await MyGlobal.prisma.erp_hrm_roles.create({
    data: await ErpHrmRoleCollector.collect({
      body: props.body,
      erpHrmOrganizations: { id: props.organizationId },
      erpHrmMembers: { id: props.member.id },
      erpHrmMemberSessions: { id: props.member.session_id },
    }),
    ...ErpHrmRoleTransformer.select(),
  });
  // Step 6: Transform and return
  return ErpHrmRoleTransformer.transform(created);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteErpHrmMemberOrganizationsOrganizationIdRolesRoleId(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
  roleId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Step 1: Verify requesting member is in the organization and holds the Owner role
  const requesterMembership =
    await MyGlobal.prisma.erp_hrm_organization_members.findFirst({
      where: {
        organization_id: props.organizationId,
        member_id: props.member.id,
        deleted_at: null,
      },
      select: {
        id: true,
        role: {
          select: {
            is_builtin: true,
            name: true,
          },
        },
      },
    });
  if (requesterMembership === null) {
    throw new HttpException(
      "Forbidden: you are not a member of this organization",
      403,
    );
  }
  if (
    !requesterMembership.role.is_builtin ||
    requesterMembership.role.name !== "Owner"
  ) {
    throw new HttpException(
      "Forbidden: only the organization Owner can delete custom roles",
      403,
    );
  }
  // Step 2: Verify the target role exists in this organization
  const targetRole = await MyGlobal.prisma.erp_hrm_roles.findFirst({
    where: {
      id: props.roleId,
      erp_hrm_organization_id: props.organizationId,
    },
    select: {
      id: true,
      name: true,
      is_builtin: true,
    },
  });
  if (targetRole === null) {
    throw new HttpException(
      "Not Found: role does not exist in this organization",
      404,
    );
  }
  // Step 3: Check if it is a built-in role
  if (targetRole.is_builtin) {
    throw new HttpException(
      "Bad Request: built-in roles cannot be deleted",
      400,
    );
  }
  // Step 4: Check if any active members are currently assigned this role
  const assignedMemberCount =
    await MyGlobal.prisma.erp_hrm_organization_members.count({
      where: {
        role_id: props.roleId,
        deleted_at: null,
      },
    });
  if (assignedMemberCount > 0) {
    throw new HttpException(
      "Conflict: the role has members assigned to it and cannot be deleted; reassign all members first",
      409,
    );
  }
  // Step 5: Delete the role (with explicit permission deletion for atomicity) and write activity log
  await MyGlobal.prisma.$transaction(async (tx) => {
    // Explicitly delete all permission codes for this role (cascade would handle it, but explicit deletion ensures atomicity)
    await tx.erp_hrm_role_permissions.deleteMany({
      where: { role_id: props.roleId },
    });
    // Delete the role itself
    await tx.erp_hrm_roles.delete({
      where: { id: props.roleId },
    });
    // Insert activity log entry recording the deletion event
    await tx.erp_hrm_activity_logs.create({
      data: {
        id: v4(),
        organization_id: props.organizationId,
        organization_member_id: requesterMembership.id,
        action_type: "role_deleted",
        target_entity_type: "role",
        target_entity_id: props.roleId,
        details: `Custom role '${targetRole.name}' was permanently deleted by the organization owner.`,
        created_at: new Date().toISOString(),
      },
    });
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IErpHrmRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmRole";
import { IErpHrmRolePermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmRolePermission";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { ErpHrmRoleTransformer } from "../transformers/ErpHrmRoleTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchErpHrmMemberOrganizationsOrganizationIdRolesRoleIdPermissions(props: {
  member: MemberPayload;
  organizationId: string & tags.Format<"uuid">;
  roleId: string & tags.Format<"uuid">;
  body: IErpHrmRolePermission.IUpdate;
}): Promise<IErpHrmRole> {
  const ALLOWED_PERMISSION_CODES: string[] = [
    "org:manage",
    "employee:manage",
    "employee:view",
    "project:manage",
    "project:view",
    "time:manage",
    "time:approve",
    "time:view_all",
    "report:view",
  ];
  // 1. Verify the requesting member belongs to this organization and is active
  const orgMember =
    await MyGlobal.prisma.erp_hrm_organization_members.findFirst({
      where: {
        member_id: props.member.id,
        organization_id: props.organizationId,
        deleted_at: null,
      },
      select: {
        id: true,
        role: {
          select: {
            name: true,
            is_builtin: true,
          },
        },
      },
    });
  if (orgMember === null) {
    throw new HttpException(
      "Forbidden: not a member of this organization",
      403,
    );
  }
  // 2. Verify the member holds the Owner built-in role
  if (!(orgMember.role.is_builtin && orgMember.role.name === "Owner")) {
    throw new HttpException(
      "Forbidden: only organization owners can update role permissions",
      403,
    );
  }
  // 3. Fetch the target role scoped to this organization (404 if not found)
  const targetRole = await MyGlobal.prisma.erp_hrm_roles.findFirstOrThrow({
    where: {
      id: props.roleId,
      erp_hrm_organization_id: props.organizationId,
    },
    select: {
      id: true,
      is_builtin: true,
    },
  });
  // 4. Reject attempts to modify built-in role permissions
  if (targetRole.is_builtin) {
    throw new HttpException(
      "Unprocessable Entity: cannot modify permissions of built-in roles",
      422,
    );
  }
  // 5. Validate all provided permission codes against the allowed catalogue
  for (const code of props.body.permissionCodes) {
    if (!ALLOWED_PERMISSION_CODES.includes(code)) {
      throw new HttpException(
        `Bad Request: unrecognized permission code '${code}'`,
        400,
      );
    }
  }
  // 6. Atomically replace the permission set within a transaction
  const now = new Date();
  await MyGlobal.prisma.$transaction(async (tx) => {
    // 6a. Remove all existing permission rows for this role
    await tx.erp_hrm_role_permissions.deleteMany({
      where: { role_id: props.roleId },
    });
    // 6b. Insert new permission rows (one per code)
    if (props.body.permissionCodes.length > 0) {
      await tx.erp_hrm_role_permissions.createMany({
        data: props.body.permissionCodes.map((code) => ({
          id: v4(),
          role_id: props.roleId,
          permission_code: code,
          created_at: now,
        })),
      });
    }
    // 6c. Bump the role's updated_at timestamp
    await tx.erp_hrm_roles.update({
      where: { id: props.roleId },
      data: { updated_at: now },
    });
  });
  // 7. Record the permission change in the organization's activity log
  await MyGlobal.prisma.erp_hrm_activity_logs.create({
    data: {
      id: v4(),
      organization_id: props.organizationId,
      organization_member_id: orgMember.id,
      action_type: "role_assigned_or_changed",
      target_entity_type: "role",
      target_entity_id: props.roleId,
      details: `Permission codes updated for role ${props.roleId}`,
      created_at: now,
    },
  });
  // 8. Return the fully updated role (with new permissions)
  const updated = await MyGlobal.prisma.erp_hrm_roles.findUniqueOrThrow({
    where: { id: props.roleId },
    ...ErpHrmRoleTransformer.select(),
  });
  return ErpHrmRoleTransformer.transform(updated);
}

