import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IErpHrmGuest } from "../../../../api/structures/IErpHrmGuest";
import { postErpHrmAuthGuestJoin } from "../../../../providers/postErpHrmAuthGuestJoin";
import { postErpHrmAuthGuestRefresh } from "../../../../providers/postErpHrmAuthGuestRefresh";

@Controller("/erpHrm/auth/guest")
export class ErphrmAuthGuestController {
  /**
   * Registers or retrieves an existing guest identity and issues a JWT-based session for the unauthenticated visitor.
   *
   * This endpoint serves as the entry point for unauthenticated visitors (guests) into the ERP HRM platform. A guest is represented in the database by an `erp_hrm_guests` record, which is uniquely identified by the client-provided `fingerprint` field — a device fingerprint or client-generated identifier used to correlate anonymous activity before account creation or login (as described in the erp_hrm_guests schema: "Device fingerprint or client-generated identifier used to uniquely identify the unauthenticated visitor across sessions").
   *
   * When a join request is received, the service checks whether a guest record with the given fingerprint already exists (using the unique index on the `fingerprint` column). If it does, that record is reused; if not, a new `erp_hrm_guests` record is created with the provided fingerprint and current timestamps (`created_at`, `updated_at`). A new `erp_hrm_guest_sessions` record is then created, capturing the client IP address (`ip`), the page URL (`href`), the HTTP referrer (`referrer`), and an expiry timestamp (`expired_at`) relative to the current time.
   *
   * Upon successful session creation, the server returns an `IErpHrmGuest.IAuthorized` response containing JWT access and refresh tokens. These tokens allow the guest to make subsequent API calls and refresh their session without re-joining. Guest sessions are append-only and are never modified after creation; they are invalidated naturally when they expire (per the erp_hrm_guest_sessions schema: "Sessions are append-only and are never updated after creation").
   *
   * This operation requires the `guest` actor context. It is the prerequisite for any token refresh operation performed by a guest actor. Once the guest completes registration or login as a member, their guest context is no longer used and they transition to an `erp_hrm_members` identity.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Guest join request payload containing the device fingerprint used to identify the unauthenticated visitor.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification 1. Accept the POST request body as IErpHrmGuest.IJoin, which must contain the device fingerprint string.
   * 2. Query the erp_hrm_guests table for an existing record with the matching fingerprint (unique index exists on fingerprint column).
   * 3. If found, use the existing erp_hrm_guests record. If not found, INSERT a new erp_hrm_guests row with a new UUID id, the provided fingerprint, and current timestamps for created_at and updated_at.
   * 4. INSERT a new erp_hrm_guest_sessions row with: a new UUID id, the erp_hrm_guest_id referencing the guest record, the client IP address extracted from the request, href and referrer from the request body or headers, created_at = now(), expired_at = now() + configured session TTL (e.g., 7 days).
   * 5. Generate a JWT access token (short-lived, e.g., 1 hour) and a refresh token (longer-lived, tied to the session record id) for the guest.
   * 6. Return IErpHrmGuest.IAuthorized containing the tokens and the guest identity (id, fingerprint, created_at).
   * 7. Edge cases: If fingerprint is empty or invalid, return 400. No rate limiting specific to this endpoint beyond global limits.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IErpHrmGuest.IJoin,
  ): Promise<IErpHrmGuest.IAuthorized> {
    try {
      return await postErpHrmAuthGuestJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renews the JWT access token for an existing guest session using a valid refresh token.
   *
   * This endpoint allows a guest actor to obtain a new JWT access token without re-joining. It accepts a refresh token previously issued by the `POST /auth/guest/join` operation and, upon validation, returns a fresh `IErpHrmGuest.IAuthorized` response with new access and refresh tokens.
   *
   * The refresh token is validated against the `erp_hrm_guest_sessions` table. The service verifies that the session record exists, that the associated `erp_hrm_guests` record is still valid, and that the session has not reached its `expired_at` timestamp (per the erp_hrm_guest_sessions schema: "Timestamp when this guest session expires. After this point the session is considered invalid and the guest must re-initiate"). If the session is expired, the request is rejected and the guest must re-join.
   *
   * Successful token refresh results in a new JWT access token (and optionally a rotated refresh token) being returned. The underlying `erp_hrm_guest_sessions` record is not modified (sessions are append-only per schema design); a new session record may be created to represent the refreshed session context, capturing updated network metadata (ip, href, referrer) and a new expired_at.
   *
   * This operation requires the `guest` actor context and only the refresh token in the request body. It is designed to maintain continuity of a guest's anonymous session across token expiry boundaries, ensuring the guest's fingerprint-based identity persists throughout their pre-registration workflow. It must be preceded by a successful join (`POST /auth/guest/join`) which provides the initial refresh token.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Guest token refresh request payload containing the current refresh token to be exchanged for a new JWT access token.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification 1. Accept the POST request body as IErpHrmGuest.IRefresh, which must contain the refresh token string.
   * 2. Decode and validate the refresh token: verify signature, extract the embedded erp_hrm_guest_session_id (or guest_id).
   * 3. Query erp_hrm_guest_sessions by the session id embedded in the token. Verify the record exists.
   * 4. Check that expired_at > now(). If expired, return 401 Unauthorized — the guest must re-join.
   * 5. Load the associated erp_hrm_guests record via erp_hrm_guest_id. Verify it exists.
   * 6. Optionally insert a new erp_hrm_guest_sessions record to represent the refreshed session (capturing current ip, href, referrer, new expired_at), maintaining the append-only audit trail.
   * 7. Generate a new JWT access token (short-lived) and a new refresh token (if rotation is used).
   * 8. Return IErpHrmGuest.IAuthorized with the new tokens and the guest identity.
   * 9. Edge cases: Invalid/malformed token → 401. Token for a non-existent session → 401. Token for a non-existent guest → 401.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IErpHrmGuest.IRefresh,
  ): Promise<IErpHrmGuest.IAuthorized> {
    try {
      return await postErpHrmAuthGuestRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

